{
  "category_edits": [
    {
      "category": "architecture_interaction",
      "rationale": "Test residual scaling of 0.45 across all four datasets, a smaller reduction from the incumbent 0.5 than the previously evaluated 0.35. Slight damping may preserve contextual updates while improving stability. Keep causal convolutions, embeddings, features, readout, scoring, loss, optimizer and training limits fixed, with one checkpoint per dataset.",
      "edits": [
        {
          "find": "        return residual + 0.5 * y",
          "replace": "        return residual + 0.45 * y"
        },
        {
          "find": "            \"residual_scale\": 0.5,",
          "replace": "            \"residual_scale\": 0.45,"
        },
        {
          "find": "        if meta.get(\"residual_scale\") != 0.5:",
          "replace": "        if meta.get(\"residual_scale\") != 0.45:"
        }
      ]
    }
  ],
  "change_summary": "Test NextItNet residual scale 0.45 for all four category models, synchronizing checkpoint metadata and the embedded predictor compatibility check."
}
